import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"八齐","description":"","frontmatter":{"title":"八齐","date":"2026-11-17T00:00:00.000Z","seq":8,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/八齐.md","filePath":"blogs/声律启蒙·上卷/八齐.md"}'),r={name:"blogs/声律启蒙·上卷/八齐.md"};function p(l,e,_,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="八齐" tabindex="-1">八齐 <a class="header-anchor" href="#八齐" aria-label="Permalink to &quot;八齐&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">岩对岫，涧对溪，远岸对危堤。鹤长对凫短，水雁对山鸡。星拱北，月流西，汉露对汤霓。桃林牛已放，虞阪马长嘶。叔侄去官闻广受，弟兄让国有夷齐。三月春浓，芍药丛中蝴蝶舞；五更天晓，海棠枝上子规啼。</p><p class="poem-stanza">云对雨，水对泥，白璧对玄圭。献瓜对投李，禁鼓对征鼙。徐稚榻，鲁班梯，凤翥对鸾栖，有官清似水，无客醉如泥。截发惟闻陶侃母，断机只有乐羊妻。秋望佳人，目送楼头千里雁；早行远客，梦惊枕上五更鸡。</p><p class="poem-stanza">熊对虎，象对犀，霹雳对虹霓。杜鹃对孔雀，桂岭对梅溪。萧史凤，宋宗鸡，远近对高低。水寒鱼不跃，林茂鸟频栖。杨柳和烟彭泽县，桃花流水武陵溪。公子追欢，闲骤玉骢游绮陌；佳人倦绣，闷欹珊枕掩香闺。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
